// Persian Date Picker with Year/Month Dropdowns
(function($){
    var months = ['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
    var dayNames = ['ش','ی','د','س','چ','پ','ج'];
    
    function g2j(gy, gm, gd) {
        var g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
        var gy2 = (gm > 2) ? (gy + 1) : gy;
        var days = 355666 + (365 * gy) + Math.floor((gy2 + 3) / 4) - Math.floor((gy2 + 99) / 100) + Math.floor((gy2 + 399) / 400) + gd + g_d_m[gm - 1];
        var jy = -1595 + (33 * Math.floor(days / 12053));
        days %= 12053; jy += 4 * Math.floor(days / 1461); days %= 1461;
        if (days > 365) { jy += Math.floor((days - 1) / 365); days = (days - 1) % 365; }
        var jd, jm;
        if (days < 186) { jm = 1 + Math.floor(days / 31); jd = 1 + (days % 31); }
        else { jm = 7 + Math.floor((days - 186) / 30); jd = 1 + ((days - 186) % 30); }
        return [jy, jm, jd];
    }
    
    function isJalaliLeap(jy) {
        var m = ((jy % 33) + 33) % 33;
        return m === 1 || m === 5 || m === 9 || m === 13 || m === 17 || m === 22 || m === 26 || m === 30;
    }

    function daysInMonth(jy, jm) {
        if (jm <= 6) return 31;
        if (jm <= 11) return 30;
        return isJalaliLeap(jy) ? 30 : 29;
    }

    // days since Farvardin 1 of 1350 (fixed epoch inside the picker's year range)
    function jdayNum(jy, jm, jd) {
        var n = 0;
        for (var y = 1350; y < jy; y++) n += isJalaliLeap(y) ? 366 : 365;
        for (var m = 1; m < jm; m++) n += daysInMonth(jy, m);
        return n + jd - 1;
    }

    // grid column of the 1st of month (jm) of year (jy); column 0 = Saturday (شنبه)
    function firstDayOfWeek(jy, jm) {
        var now = new Date();
        var jt = g2j(now.getFullYear(), now.getMonth() + 1, now.getDate());
        var delta = jdayNum(jy, jm, 1) - jdayNum(jt[0], jt[1], jt[2]);
        var gFirst = new Date(now.getFullYear(), now.getMonth(), now.getDate() + delta);
        return (gFirst.getDay() + 1) % 7;
    }
    
    $.fn.persianDatepicker = function(options) {
        var opts = $.extend({
            format: 'YYYY/MM/DD',
            autoClose: true,
            initialValue: false
        }, options);
        
        return this.each(function() {
            var $input = $(this);
            var $container = null;
            var year = 1403, month = 1;
            
            $input.attr('readonly', true).css('cursor', 'pointer');
            
            if ($input.val()) {
                var parts = $input.val().replace(/[\/\-]/g, '/').split('/');
                if (parts.length === 3) {
                    year = parseInt(parts[0]) || 1403;
                    month = parseInt(parts[1]) || 1;
                }
            } else if (opts.initialValue) {
                var now = new Date();
                var j = g2j(now.getFullYear(), now.getMonth() + 1, now.getDate());
                year = j[0]; month = j[1];
            }
            
            function show() {
                hide();
                var rect = $input[0].getBoundingClientRect();
                var top = rect.bottom + window.scrollY + 5;
                var left = rect.left;
                if (top + 350 > window.innerHeight + window.scrollY) top = rect.top + window.scrollY - 360;
                if (left + 280 > window.innerWidth) left = window.innerWidth - 290;
                if (left < 10) left = 10;
                
                $container = $('<div class="pdp-popup"></div>').css({
                    position: 'absolute', top: top + 'px', left: left + 'px',
                    zIndex: 99999, background: '#fff', border: '2px solid #c44dff',
                    borderRadius: '12px', padding: '12px',
                    boxShadow: '0 4px 20px rgba(0,0,0,0.2)',
                    minWidth: '280px', direction: 'rtl', fontFamily: 'Vazirmatn, sans-serif'
                });
                render();
                $('body').append($container);
            }
            
            function hide() { $('.pdp-popup').remove(); $container = null; }
            
            function render() {
                if (!$container) return;
                var days = daysInMonth(year, month);
                var firstDay = firstDayOfWeek(year, month);
                
                var html = '<div style="margin-bottom:8px;">';
                html += '<select class="pdp-year" style="padding:4px 8px;border:1px solid #ddd;border-radius:6px;font-family:Vazirmatn;font-size:0.85rem;margin-left:4px;">';
                for (var y = 1350; y <= 1450; y++) {
                    html += '<option value="' + y + '"' + (y === year ? ' selected' : '') + '>' + y + '</option>';
                }
                html += '</select>';
                html += '<select class="pdp-month" style="padding:4px 8px;border:1px solid #ddd;border-radius:6px;font-family:Vazirmatn;font-size:0.85rem;">';
                for (var m = 1; m <= 12; m++) {
                    html += '<option value="' + m + '"' + (m === month ? ' selected' : '') + '>' + months[m-1] + '</option>';
                }
                html += '</select>';
                html += '</div>';
                
                html += '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center;font-size:0.7rem;color:#888;margin-bottom:4px;">';
                for (var i = 0; i < 7; i++) html += '<div>' + dayNames[i] + '</div>';
                html += '</div>';
                
                html += '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center;">';
                for (var j = 0; j < firstDay; j++) html += '<div></div>';
                for (var d = 1; d <= days; d++) {
                    html += '<div class="pdp-day" data-day="' + d + '" style="padding:6px 0;cursor:pointer;border-radius:6px;font-size:0.85rem;">' + d + '</div>';
                }
                html += '</div>';
                
                html += '<div style="display:flex;justify-content:space-between;margin-top:8px;border-top:1px solid #eee;padding-top:8px;">';
                html += '<button class="pdp-today" style="background:#c44dff;color:#fff;border:none;padding:4px 12px;border-radius:8px;cursor:pointer;font-size:0.8rem;">امروز</button>';
                html += '<button class="pdp-clear" style="background:#ff6b6b;color:#fff;border:none;padding:4px 12px;border-radius:8px;cursor:pointer;font-size:0.8rem;">پاک کردن</button>';
                html += '</div>';
                
                $container.html(html);
                
                // Stop propagation on ALL interactive elements inside popup
                $container.on('click', 'select, option, button, .pdp-day', function(e) {
                    e.stopPropagation();
                });
                
                $container.find('.pdp-year').change(function(e) {
                    e.stopPropagation();
                    year = parseInt($(this).val());
                    render();
                });
                $container.find('.pdp-month').change(function(e) {
                    e.stopPropagation();
                    month = parseInt($(this).val());
                    render();
                });
                $container.find('.pdp-today').click(function(e) {
                    e.stopPropagation();
                    var now = new Date();
                    var j = g2j(now.getFullYear(), now.getMonth() + 1, now.getDate());
                    year = j[0]; month = j[1];
                    selectDay(j[2]);
                });
                $container.find('.pdp-clear').click(function(e) {
                    e.stopPropagation();
                    $input.val('');
                    hide();
                });
                $container.find('.pdp-day').click(function(e) {
                    e.stopPropagation();
                    selectDay(parseInt($(this).data('day')));
                });
                $container.find('.pdp-day').hover(
                    function() { $(this).css('background', '#f0e6ff'); },
                    function() { $(this).css('background', 'transparent'); }
                );
            }
            
            function selectDay(d) {
                $input.val(year + '/' + String(month).padStart(2, '0') + '/' + String(d).padStart(2, '0'));
                if (opts.autoClose) hide();
                if (opts.onSelect) opts.onSelect(year, month, d);
            }
            
            $input.click(function(e) {
                e.stopPropagation();
                if ($container) hide();
                else show();
            });
            
            // Only close on click OUTSIDE the popup
            $(document).on('click', function(e) {
                if ($container && !$container[0].contains(e.target) && e.target !== $input[0]) {
                    hide();
                }
            });
        });
    };
})(jQuery);
